using HakutaiKagami.Core.Appearance;
using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
public class SceneryAppearanceTests
{
 static SceneryAppearanceCatalog Catalog(){var root=new DirectoryInfo(AppContext.BaseDirectory);while(root!=null&&!File.Exists(Path.Combine(root.FullName,"Game/Data/Scenery/scenery-appearance-v1.json")))root=root.Parent;return SceneryAppearance.Read(File.ReadAllBytes(Path.Combine(root!.FullName,"Game/Data/Scenery/scenery-appearance-v1.json")));}
 [Fact] public void CompleteCatalogBindsEveryRoleToExplicitIds(){var c=Catalog();foreach(var skin in c.Skins)foreach(var role in SceneryAppearance.Roles)Assert.Equal(role,SceneryAppearance.Resolve(c,skin.Id,SceneryAppearance.Appearance(role)).Role);}
 [Fact] public void ReorderingCatalogDoesNotChangeLayoutOrChosenIds(){var c=Catalog();var before=SceneryAppearance.PlacementHash;var d=c with{Materials=c.Materials.Reverse().ToArray(),Visuals=c.Visuals.Reverse().ToArray(),Skins=c.Skins.Reverse().Select(s=>s with{Bindings=s.Bindings.Reverse().ToArray()}).ToArray()};SceneryAppearance.Validate(d);foreach(var p in SceneryAppearance.Placements())Assert.Equal(SceneryAppearance.Resolve(c,c.DefaultSkin,p.Appearance).Id,SceneryAppearance.Resolve(d,d.DefaultSkin,p.Appearance).Id);Assert.Equal(before,SceneryAppearance.PlacementHash);Assert.Equal(SceneryAppearance.Placements().Length,SceneryAppearance.Placements().Select(p=>p.Id).Distinct().Count());}
 [Fact] public void AddingVariantsDoesNotRerollExistingChoices(){var c=Catalog();var before=SceneryAppearance.Placements();var d=c with{Visuals=c.Visuals.Select(v=>v.Id=="visual:rock-demo"?v with{Variants=[..v.Variants,new("variant:c","res://Assets/Scenery/Models/rock-demo-a.tscn")]}:v).ToArray()};SceneryAppearance.Validate(d);Assert.Equal(before,SceneryAppearance.Placements());Assert.All(before,p=>Assert.Contains(p.Variant,new[]{"variant:a","variant:b"}));}
 [Fact] public void MaterialAndMeshChangesDoNotChangeWorldDefinitionOrMovement(){var c=Catalog();var w=RegionalScenery.Create();var a=new WorldSession(w);var b=new WorldSession(w);var request=new RegionalRequest(new("request:unchanged"),ContractFixture.Officer,ContractFixture.Officer,RegionalAction.Move,new(25000,25000),new(65000,-25000));a.IssueRegional(request,a.Revision);var d=c with{Materials=c.Materials.Select(m=>m.Id=="material:surface/road"?m with{Color="875f42"}:m).ToArray()};SceneryAppearance.Validate(d);Assert.NotEqual(ContractJson.CanonicalHash(c),ContractJson.CanonicalHash(d));b.IssueRegional(request,b.Revision);a.AdvanceTo(300);b.AdvanceTo(300);Assert.Equal(ContractJson.Write(a.DiagnosticSnapshot()),ContractJson.Write(b.DiagnosticSnapshot()));Assert.Equal(ContractJson.Write(w.Definitions),ContractJson.Write(RegionalScenery.Create().Definitions));}
 [Theory][InlineData("duplicate")][InlineData("missing-material")][InlineData("bad-color")][InlineData("cycle")][InlineData("missing-binding")][InlineData("ground-scene")][InlineData("missing-fallback")] public void InvalidCatalogFailsBeforeRendering(string fault){var c=Catalog();c=fault switch{"duplicate"=>c with{Visuals=[..c.Visuals,c.Visuals[0]]},"missing-material"=>c with{Visuals=c.Visuals.Select((v,i)=>i==0?v with{Material="material:none"}:v).ToArray()},"bad-color"=>c with{Materials=c.Materials.Select((m,i)=>i==0?m with{Color="wrong"}:m).ToArray()},"cycle"=>c with{Visuals=c.Visuals.Select(v=>v.Id=="visual:rock-demo"?v with{Fallback=v.Id}:v).ToArray()},"missing-binding"=>c with{Skins=c.Skins.Select((s,i)=>i==0?s with{Bindings=s.Bindings.Skip(1).ToArray()}:s).ToArray()},"ground-scene"=>c with{Visuals=c.Visuals.Select((v,i)=>i==0?v with{Builder="scene",Variants=[new("variant:a","res://Assets/Scenery/Models/rock-demo-a.tscn")],Fallback="visual:surface/road"}:v).ToArray()},_=>c with{Visuals=c.Visuals.Select(v=>v.Id=="visual:rock-demo"?v with{Fallback="visual:none"}:v).ToArray()}};Assert.Throws<InvalidDataException>(()=>SceneryAppearance.Validate(c));}
 [Theory][InlineData("user://models/a.tscn")][InlineData("res://Assets/Scenery/../private.tscn")][InlineData("C:/model.glb")][InlineData("res://Scripts/a.cs")][InlineData("https://example.com/rock.tscn")] public void AssetPathsStayWithinTheSceneryResourceDirectory(string path){var c=Catalog();c=c with{Visuals=c.Visuals.Select(v=>v.Id=="visual:rock-demo"?v with{Variants=[new("variant:a",path)]}:v).ToArray()};Assert.Throws<InvalidDataException>(()=>SceneryAppearance.Validate(c));}
 [Fact] public void OptionalSkinKeepsPreviousPresentationJsonReadableAndUnchanged(){var bytes=ContractJson.Write(new SavePresentation(.375,1));Assert.DoesNotContain("ScenerySkin",System.Text.Encoding.UTF8.GetString(bytes));Assert.Null(ContractJson.Read<SavePresentation>(bytes).ScenerySkin);var current=new SavePresentation(.375,1,"skin:swap-demo");Assert.Equal(current,ContractJson.Read<SavePresentation>(ContractJson.Write(current)));}
 [Fact] public void SavingDifferentSkinsPreservesWorldAndRestoresTheSkin(){var s=new WorldSession(RegionalScenery.Create());s.IssueRegional(new(new("request:skin-save"),ContractFixture.Officer,ContractFixture.Officer,RegionalAction.Move,new(25000,25000),new(65000,-25000)),s.Revision);s.AdvanceTo(55);var before=ContractJson.Write(s.DiagnosticSnapshot());var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"skin-"+Guid.NewGuid().ToString("N")),s.DiagnosticSnapshot().Definitions);foreach(var skin in new[]{"skin:baseline","skin:swap-demo"}){store.Save(s,skin.Replace(':','-'),s.DiagnosticSnapshot().WorldId,new(.375,1,skin));var p=store.Prepare(skin.Replace(':','-'));Assert.Equal(skin,p.Presentation.ScenerySkin);Assert.Equal(before,ContractJson.Write(s.DiagnosticSnapshot()));var host=new WorldSessionHost(new(RegionalScenery.Create()));Assert.Equal(ResultCode.Accepted,host.CommitLoad(p,host.Current,host.Current.Revision));Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot().Region),ContractJson.Write(host.Current.DiagnosticSnapshot().Region));}}
 [Fact] public void EveryBlockedObjectKeepsItsOriginalFootprint(){var placements=SceneryAppearance.Placements();foreach(var o in RegionalScenery.Obstacles){var p=placements.Single(p=>p.SourceId==o.Id);Assert.Equal(o.Min,p.FootMin);Assert.Equal(o.Max,p.FootMax);Assert.Equal(o.HeightMm,p.HeightMm);Assert.False(RegionalGround.Walkable(p.Point,true));}}
 [Fact] public void RegionPrefixPreventsObjectIdCollisions(){var a=SceneryAppearance.Placements();var b=SceneryAppearance.Placements("region:neighbor-trial-v1");Assert.Empty(a.Select(p=>p.Id).Intersect(b.Select(p=>p.Id)));Assert.Equal(a.Select(p=>p.SourceId),b.Select(p=>p.SourceId));}
}
